from collections import deque

graph = {
    'A': ['B', 'C'],
    'B': ['A', 'D'],
    'C': ['A', 'E'],
    'D': ['B', 'F'],
    'E': ['C', 'F'],
    'F': ['D', 'E'],
}

def bfs(start):
    visited = {start}
    q = deque([start])
    order = []
    while q:
        v = q.popleft()
        order.append(v)
        for w in graph[v]:
            if w not in visited:
                visited.add(w)
                q.append(w)
    return order

print(''.join(bfs('A')))
print(''.join(bfs('E')))
